tool_input.command:
B=http://localhost:8080/api; H='Content-Type: application/json'; W() { :; }; curl -s -w '
== seed T1 due today TODO HTTP %{http_code}
' -H "$H" -d '{"title":"T1 due today","dueDate":"2026-09-26"}' $B/tasks \
 --next -s -w '
== seed T2 due today IN_PROGRESS HTTP %{http_code}
' -H "$H" -d '{"title":"T2 due today in progress","dueDate":"2026-09-26","status":"IN_PROGRESS","priority":"HIGH"}' $B/tasks \
 --next -s -w '
== seed T3 due yesterday HTTP %{http_code}
' -H "$H" -d '{"title":"T3 overdue yesterday","dueDate":"2026-09-25"}' $B/tasks \
 --next -s -w '
== seed T4 due 09-20 IN_PROGRESS HTTP %{http_code}
' -H "$H" -d '{"title":"T4 overdue last week","dueDate":"2026-09-20","status":"IN_PROGRESS"}' $B/tasks \
 --next -s -w '
== seed T5 due today (to archive) HTTP %{http_code}
' -H "$H" -d '{"title":"T5 due today archived","dueDate":"2026-09-26"}' $B/tasks \
 --next -s -w '
== seed T6 due yesterday (to archive) HTTP %{http_code}
' -H "$H" -d '{"title":"T6 overdue archived","dueDate":"2026-09-25"}' $B/tasks \
 --next -s -w '
== seed T7 no due (to complete) HTTP %{http_code}
' -H "$H" -d '{"title":"T7 completed today"}' $B/tasks \
 --next -s -w '
== seed T8 due 09-24 (to complete) HTTP %{http_code}
' -H "$H" -d '{"title":"T8 past due but done","dueDate":"2026-09-24"}' $B/tasks \
 --next -s -w '
== seed T9 (to complete then archive) HTTP %{http_code}
' -H "$H" -d '{"title":"T9 completed then archived"}' $B/tasks \
 --next -s -w '
== seed T10 due today (to delete) HTTP %{http_code}
' -H "$H" -d '{"title":"T10 due today deleted","dueDate":"2026-09-26"}' $B/tasks \
 --next -s -w '
== seed T11 due tomorrow HTTP %{http_code}
' -H "$H" -d '{"title":"T11 due tomorrow","dueDate":"2026-09-27"}' $B/tasks \
 --next -s -w '
== seed T12 due tomorrow HTTP %{http_code}
' -H "$H" -d '{"title":"T12 due tomorrow too","dueDate":"2026-09-27"}' $B/tasks \
 --next -s -w '
== T5 archive HTTP %{http_code}
' -X POST $B/tasks/5/archive \
 --next -s -w '
== T6 archive HTTP %{http_code}
' -X POST $B/tasks/6/archive \
 --next -s -w '
== T7 complete HTTP %{http_code}
' -X POST $B/tasks/7/complete \
 --next -s -w '
== T8 complete HTTP %{http_code}
' -X POST $B/tasks/8/complete \
 --next -s -w '
== T9 complete HTTP %{http_code}
' -X POST $B/tasks/9/complete \
 --next -s -w '
== T9 archive HTTP %{http_code}
' -X POST $B/tasks/9/archive \
 --next -s -w '
== T10 delete HTTP %{http_code}
' -X DELETE $B/tasks/10 >> curl.log; grep '^==' curl.log | tail -19

B=http://localhost:8080/api; H='Content-Type: application/json'; curl -s -w '
== A3 T3 complete HTTP %{http_code}
' -X POST $B/tasks/3/complete --next -s -w '
== A3 T4 complete HTTP %{http_code}
' -X POST $B/tasks/4/complete --next -s -w '
== A3 dashboard after completing T3,T4 HTTP %{http_code}
' $B/dashboard \
 --next -s -w '
== A4 H2 complete today HTTP %{http_code}
' -H "$H" -d '{}' $B/habits/2/completions --next -s -w '
== A4 dashboard after H2 complete HTTP %{http_code}
' $B/dashboard \
 --next -s -w '
== A4 H1 undo today HTTP %{http_code}
' -X DELETE $B/habits/1/completions/2026-09-26 --next -s -w '
== A4 dashboard after H1 undo HTTP %{http_code}
' $B/dashboard \
 --next -s -w '
== A5 delete C1 HTTP %{http_code}
' -X DELETE $B/learning-cards/1 --next -s -w '
== A5 dashboard after C1 delete HTTP %{http_code}
' $B/dashboard --next -s -w '
== A5 cards list HTTP %{http_code}
' $B/learning-cards \
 --next -s -w '
== A6 P1 get HTTP %{http_code}
' $B/plans/1 --next -s -w '
== A6 P2 get HTTP %{http_code}
' $B/plans/2 >> curl.log
for l in 'A3 dashboard after' 'A4 dashboard after H2' 'A4 dashboard after H1' 'A5 dashboard after'; do echo "$l:"; grep -B1 "== $l" curl.log | head -1 | jq -c '{overdue:[.overdue[].id], completedToday:[.completedToday[].id], dueToday:[.dueToday[].id], taskCompletionPercent, taskCounts, habits:[.habits[]|[.id,.completedToday]], habitCounts, learning}'; done; grep -B1 '== A5 cards list' curl.log | head -1 | jq -c '[.[]|[.id,.status,.milestonesDone,.milestonesTotal]]'; grep -B1 -E '== A6 P[12] get' curl.log | grep -v '^==' | jq -c '{id,items:[.items[]|[.id,.sourceType,.sourceId,.done]]}'
